//! mdrev, PINNED (#274): the embedding kit of one public mdrev release, vendored under `release/`
//! and built into the binaries that depend on this crate — `agent-monitor` and `agent-monitor-v2`,
//! through `claude-monitor`. `README.md` beside this crate says which release, where it came from
//! and how the pin moves; `design/mdrev-in-the-preview-pane.md` says what the monitor does with it.
//!
//! The owner, 2026-09-25: "only depend on static version of mdrev, similar to how agent-monitor
//! depends on crates in claude-replay. Future upgrades will be triggered explicitly and manually".
//! So nothing here looks at the machine: the version in the repository is the dependency, and
//! `scripts/vendor-mdrev.sh` is the only thing that moves it.
//!
//! Plain data, with no dependency on the crates that serve it, so only a binary that names these
//! items carries the bytes — `agent-replay` carries none of them.

/// The pinned release's version: this crate's own, which `scripts/vendor-mdrev.sh` sets from the
/// release's `package.json` (a test holds the two together).
pub const VERSION: &str = env!("CARGO_PKG_VERSION");

// `BUNDLE`, generated by build.rs from `release/bundle/`.
include!(concat!(env!("OUT_DIR"), "/bundle.rs"));

/// `mdrev-cli.js`, the release's command line — its note store and its revision list — which the
/// monitor writes out and runs with node.
pub static CLI: &[u8] = include_bytes!("../release/mdrev-cli.js");

/// The release's `package.json`, written beside the CLI: `mdrev-cli --version` reads it there.
pub static PACKAGE_JSON: &[u8] = include_bytes!("../release/package.json");

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::{Path, PathBuf};

    fn release() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR")).join("release")
    }

    /// Every file under `dir`, relative to it with `/` separators, sorted.
    fn files(dir: &Path) -> Vec<String> {
        fn walk(base: &Path, dir: &Path, out: &mut Vec<String>) {
            for e in std::fs::read_dir(dir).unwrap() {
                let p = e.unwrap().path();
                if p.is_dir() {
                    walk(base, &p, out);
                } else {
                    let rel = p.strip_prefix(base).unwrap();
                    let parts: Vec<_> = rel.iter().map(|s| s.to_str().unwrap()).collect();
                    out.push(parts.join("/"));
                }
            }
        }
        let mut out = Vec::new();
        walk(dir, dir, &mut out);
        out.sort();
        out
    }

    #[test]
    fn the_crate_version_is_the_release_s_own() {
        let pkg: serde_json::Value = serde_json::from_slice(PACKAGE_JSON).unwrap();
        assert_eq!(
            pkg["version"].as_str(),
            Some(VERSION),
            "vendor-mdrev.sh sets both — one of them was moved by hand"
        );
    }

    /// `release/` is what the release shipped, byte for byte: every file `release.sha256` lists,
    /// with that checksum, and nothing it does not list.
    #[test]
    fn the_vendored_tree_is_the_release_byte_for_byte() {
        use sha2::{Digest, Sha256};
        let manifest = Path::new(env!("CARGO_MANIFEST_DIR")).join("release.sha256");
        let manifest = std::fs::read_to_string(manifest).unwrap();
        let mut listed = Vec::new();
        for line in manifest.lines() {
            let (hash, path) = line.split_once("  ").expect("`<sha256>  <path>`");
            let bytes =
                std::fs::read(release().join(path)).unwrap_or_else(|e| panic!("{path}: {e}"));
            let got: String = Sha256::digest(&bytes)
                .iter()
                .map(|b| format!("{b:02x}"))
                .collect();
            assert_eq!(
                got, hash,
                "{path} is not the file the release shipped — re-vendor with scripts/vendor-mdrev.sh, never edit"
            );
            listed.push(path.to_string());
        }
        listed.sort();
        assert_eq!(
            files(&release()),
            listed,
            "a file was added to or dropped from release/ by hand"
        );
    }

    /// What build.rs embedded is the directory as it stands — the guard against a table built from a
    /// tree that has since changed under it.
    #[test]
    fn the_bundle_table_is_the_bundle_directory() {
        let dir = release().join("bundle");
        let names: Vec<&str> = BUNDLE.iter().map(|(p, _)| *p).collect();
        assert_eq!(names, files(&dir));
        assert!(
            names.windows(2).all(|w| w[0] < w[1]),
            "sorted and unique: the monitor binary-searches it"
        );
        assert!(names.contains(&"mdrev.js") && names.contains(&"mdrev.css"));
        for (path, bytes) in BUNDLE {
            assert_eq!(
                *bytes,
                std::fs::read(dir.join(path)).unwrap().as_slice(),
                "{path}"
            );
        }
    }

    /// The options the preview pane declares — `toolbar` (1.1.6-dev9) and the `review`/`annotate`
    /// ceilings (1.1.6-dev11), in mdrev's own history — are understood from 1.1.6 on. An older
    /// guest would take them as nothing and draw its toolbar over Markdown the owner asked to be
    /// read clean.
    #[test]
    fn the_pin_understands_what_the_pane_declares() {
        let (core, pre) = match VERSION.split_once('-') {
            Some((c, _)) => (c, true),
            None => (VERSION, false),
        };
        let n: Vec<u64> = core.split('.').map(|p| p.parse().unwrap()).collect();
        let v = (n[0], n[1], n[2]);
        assert!(
            v > (1, 1, 6) || (v == (1, 1, 6) && !pre),
            "mdrev {VERSION} predates the options the pane declares"
        );
    }

    #[test]
    fn the_version_is_a_url_segment() {
        assert!(
            !VERSION.is_empty()
                && VERSION
                    .bytes()
                    .all(|b| b.is_ascii_alphanumeric() || b == b'.' || b == b'-'),
            "the bundle is served under /mdrev/<version>/: {VERSION}"
        );
    }
}
